            "양쪽 차선이 확실할 때(확률 0.6↑, 표준편차 0.3↓, 폭 2.6~4.8m)만 동작하고, "
            "차선변경 중이거나 5m/s 미만이면 부드럽게 풀립니다. ISO 저크·횡가속 한계 위에서 "
